(async()=>{
  const E=window.__echoes;
  const out={scene:E.state().scene, version:E.version};
  out.pre=E.cmd('runState');
  E.cmd('startRun');
  await new Promise(r=>setTimeout(r,600));
  const v=E.cmd('runState');
  out.frame=v.frame; out.room=v.room; out.phase=v.phase; out.mode=v.mode; out.wallet=v.wallet; out.rewardFor=v.rewardFor; out.free=v.freeSkillSlots;
  out.seed=E.seed;
  out.evt=E.events.slice(-12).map(e=>e.tick+':'+e.type);
  return out;
})()
